from pathlib import Path
import re, shutil, json

root=Path.cwd(); paper=root/'paper'; sections=paper/'sections'
backup=root/'.runtime/paper_before_sacj_style'
if backup.exists():raise FileExistsError('The style revision has already been backed up.')
backup.mkdir(parents=True)
for p in paper.rglob('*.tex'):
    if 'build' not in p.relative_to(paper).parts:
        dest=backup/p.relative_to(paper);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)

changes=[]
def replace_paragraph(filename,starts,new):
    path=sections/filename;s=path.read_text(encoding='utf-8')
    pattern=re.compile(r'(?m)^'+re.escape(starts)+r'[^\n]*')
    found=list(pattern.finditer(s));assert len(found)==1,(filename,starts,len(found))
    m=found[0];s=s[:m.start()]+new+s[m.end():];path.write_text(s,encoding='utf-8');changes.append((filename,starts))
def replace_text(filename,old,new):
    path=sections/filename;s=path.read_text(encoding='utf-8');assert old in s,(filename,old);path.write_text(s.replace(old,new),encoding='utf-8')

(sections/'00_abstract.tex').write_text(r'''\begin{abstract}
This study investigates interpretable unsupervised machine learning for identifying financial peer groups and changes in their membership among JSE Top 40 equities. The analysis extends a single-window study to three cross-sections: 30 June 2025, 31 December 2025 and 30 June 2026. Each cross-section contains 41 listed instruments representing 40 company groups. Eight financial variables were transformed using a June 2025 scaling reference and analysed through UMAP dimensionality reduction followed by hierarchical clustering with average linkage and Manhattan distance. Eight clusters were fitted independently at each date, and stability was assessed over five random seeds. The UMAP partitions achieved Silhouette Scores of 0.685, 0.638 and 0.721 in the reduced representations, compared with 0.151, 0.124 and 0.267 in the scaled financial features. Clusters were matched between dates using Jaccard similarity and a Hungarian assignment. Among 40 continuing instruments, 15 changed aligned group in the first period and 11 in the second. Of the 39 instruments present at all three dates, 19 retained their aligned group and 20 changed at least once. Cluster profiles, company-level feature changes, surrogate SHAP explanations and a separate Mahalanobis distance screen were used to interpret the results. The findings show how repeated clustering can support equity screening by identifying continuing and changing financial relationships. Retrospective data, representation sensitivity and incomplete external validation limit the conclusions that can be drawn about economic anomalies or investment performance.
\end{abstract}

Keywords: unsupervised learning; clustering; repeated cross-sections; dimensionality reduction; interpretable artificial intelligence; JSE Top 40; financial data mining.
''',encoding='utf-8')

replace_paragraph('01_introduction.tex','The approach proposed by the paper',r'''The approach proposed by the paper is fourfold. First, the study extends the analysis to three decision dates, allowing financial peer groups to be compared over time. Second, UMAP is combined with hierarchical clustering, and cluster quality is evaluated in both the reduced representation and the scaled financial features. The earlier t-SNE hierarchical specification is retained as a comparator. Third, clusters are matched between dates using the membership of continuing instruments, so index entries and exits are separated from changes in peer-group membership. Fourth, cluster profiles, company-level feature changes, surrogate SHAP explanations and multivariate distance screening are combined to make the results easier to interpret. The research question is: Can interpretable unsupervised machine learning identify financial peer groups among JSE Top 40 equities, and how do these groups and their measured financial characteristics change across repeated cross-sections?''')
replace_paragraph('01_introduction.tex','The article is positioned',r'''The article is positioned as exploratory financial data mining rather than predictive modelling. It does not claim to forecast future returns, determine fair value or generate a trading strategy. Its purpose is to show how interpretable unsupervised learning can support analyst attention by highlighting financial similarities, changes in peer relationships and unusual multivariate profiles. The repeated design also allows these findings to be examined in relation to index membership, feature definitions and model stability.''')
replace_paragraph('01_introduction.tex','Section 2 reviews',r'''The remainder of the paper is structured as follows: Section 2 reviews related work, Section 3 describes the data and methodology, Section 4 presents the results, Section 5 discusses their implications, Section 6 outlines limitations and future work and Section 7 concludes.''')

replace_text('02_related_work.tex',r'\citep{arbelaitz2013}; \citep{vendramin2010}',r'\citep{arbelaitz2013,vendramin2010}')
replace_text('02_related_work.tex',r'models. \citep{merrick2020}; \citep{rozemberczki2022}.',r'models \citep{merrick2020,rozemberczki2022}.')

replace_text('03_population_and_inputs.tex',r'\section{Study population and financial inputs}',r'\section{Data and methodology}')
replace_text('03_population_and_inputs.tex',r'\subsection{Three decision dates and effective index membership}',r'\subsection{Dataset and index membership}')
replace_paragraph('03_population_and_inputs.tex','The unit of analysis',r'''The dataset contains three cross-sections of FTSE/JSE Top 40 instruments observed or reconstructed for 30 June 2025, 31 December 2025 and 30 June 2026. Each cross-section contains 41 listed instruments representing 40 company groups. The difference arises because Investec Limited (INL) and Investec plc (INP) are separate listed securities of one dual-listed company. Both instruments were retained because the analysis compares listed security profiles. Table~\ref{tab:1} summarises the population at each decision date.''')
replace_paragraph('03_population_and_inputs.tex','The June 2025 review introduced',r'''Index membership was reconciled against the effective-dated quarterly reviews. Northam Platinum replaced Glencore before the June 2025 observation. Glencore returned in September 2025, replacing Aspen, while the December review recorded no Top 40 change. Pan African Resources replaced Mondi in March 2026, and no change was recorded in June 2026. These changes are important because an instrument entering or leaving the index should not be treated as an ordinary change in financial peer group. Figure~\ref{fig:population} shows the date-specific populations and the instruments available for comparison.''')
replace_paragraph('03_population_and_inputs.tex','The annual market windows overlap',r'''The market variables use trailing annual windows, as shown in Figure~\ref{fig:windows}. Adjacent windows overlap by six months.''')
replace_paragraph('03_population_and_inputs.tex','Across dates there are',r'''Across the three dates, the dataset contains 123 instrument-date records and 43 distinct tickers. Forty instruments continue between each adjacent pair, and 39 are present at all three dates. Aspen is observed only in June 2025, Mondi at the first two dates, Glencore at the last two and Pan African Resources only in June 2026. The full three-date membership diagram therefore contains 39 instruments, while the clustering analysis retains all 41 instruments at each date. Because firms recur, annual windows overlap and some issuer accounts are used more than once, the 123 records do not represent 123 independent companies.''')
replace_text('03_population_and_inputs.tex',r'\subsection{Financial representation and measurement}',r'\subsection{Financial feature representation}')
replace_paragraph('03_population_and_inputs.tex','The eight-feature representation',r'''The clustering input contains eight financial and market variables, summarised in Table~\ref{tab:2}. Returns, beta, volatility, dividend yield and earnings yield describe performance, risk and valuation. Log market capitalisation, log revenue relative to market capitalisation and log share turnover describe scale and trading activity. This representation was developed after exploratory analysis to reduce skewness and the effect of share subdivisions. It extends the earlier study but uses a different sample and feature definition from the original eleven-variable SACJ analysis. The archived ten-variable specification is retained as a separate reference.''')
replace_paragraph('03_population_and_inputs.tex','For a subdivision factor',r'''The treatment of share subdivisions is particularly important for comparisons over time. For a subdivision factor $q$, price and EPS are divided by $q$, while shares and consistently measured share volume are multiplied by $q$. Earnings yield, market capitalisation, revenue relative to market capitalisation and share turnover are unchanged when these quantities are measured on a consistent basis. However, a trailing-volume series can contain both old and new share units. Such a series must be corrected before turnover is calculated.''')
replace_paragraph('03_population_and_inputs.tex','Original source values remain',r'''The original source values were preserved, and corrections were applied through separate reference tables. Naspers began trading on a five-for-one share basis on 1 October 2025, with the register updated on 6 October. Its trailing average volume contained mixed share units. The December 2025 value was corrected from 800,935 to 2,140,029 post-subdivision shares, and the June 2026 value from 1,502,524 to 1,847,639. These corrections place volume on the same share basis as the corresponding shares outstanding.''')
replace_paragraph('03_population_and_inputs.tex','Both Investec rows originally',r'''The Investec observations required a separate adjustment because both rows originally carried the combined share count. Issuer disclosures from June 2024 and June 2026 were used to allocate the reconstructed group total between the two listed lines. The December 2025 allocation uses the midpoint of the disclosed fractions. Each line then has its own market capitalisation and turnover. Revenue relative to market capitalisation uses group totals because each line represents a claim on the dual-listed group. The reconstructed total and the interpolated December allocation remain sources of measurement uncertainty.''')
replace_paragraph('03_population_and_inputs.tex','Reinet has no usable',r'''Missing observations were handled without removing instruments from the sample. Reinet has no usable raw revenue or EPS at any date, while Anglo American lacks usable volume at the first two dates. Model values were imputed using June 2025 medians. Where a derived feature depends on an imputed input, its own June 2025 median was used. Earnings yield was clipped at the June 2025 first and ninety-ninth percentiles. These imputation and clipping values were held constant at the later dates.''')
replace_paragraph('03_population_and_inputs.tex','Market measures are rebuilt',r'''Market measures were reconstructed from vendor daily histories. Dated issuer releases support revenue and diluted EPS for 120 of the 123 records, with dated currency conversions, while historical shares and market capitalisation remain reconstructed. Sector labels come from a legacy eight-category directory classification and were excluded from model fitting and selection. JSE-only volume may understate total trading activity for firms with major overseas listings, and revenue definitions differ across sectors. These data limitations are considered when interpreting the results.''')

replace_text('04_methods.tex',r'\section{Repeated cross sectional methods}',r'% Method subsections continue Section 3 Data and methodology.')
replace_paragraph('04_methods.tex','For feature j, let',r'''MinMax scaling was applied because the financial variables have different magnitudes. The scaling parameters were estimated from June 2025 and applied unchanged to December 2025 and June 2026. This provides a common reference for comparing financial profiles over time. Let $x_{itj}$ denote feature $j$ for instrument $i$ at date $t$, and let $U_{t_1}$ be the June 2025 population. The scaled value is given by Equation~\ref{eq:scale}. Scaling was not clipped, so later observations may fall outside $[0,1]$.''')
replace_paragraph('04_methods.tex','For each date and each seed',r'''UMAP was used to produce a two-dimensional representation of each cross-section \citep{mcinnes2018}. The model used three neighbours, a minimum distance of 0.01, Euclidean input distance and one computational job. Hierarchical clustering was then applied to the UMAP coordinates using average linkage and Manhattan distance, with eight clusters as the reference configuration. Each date was fitted independently using seeds 42--46. Seed 42 provides the representative partition, while the remaining fits support stability analysis. Figure~\ref{fig:pipeline} summarises the modelling workflow.''')
replace_paragraph('04_methods.tex','Three neighbours and minimum distance',r'''The settings were selected after exploratory analysis of June 2025 and held constant at the later dates. Three neighbours and a minimum distance of 0.01 were author-specified in that exploration; an earlier 36-combination grid preferred a minimum distance of 0.1. Eight clusters, average linkage and Manhattan distance were retained from the earlier paper. The specification is therefore exploratory rather than prospectively registered. Holding the settings constant supports comparison across dates, but each representation and partition is refitted, so the later results are not an out-of-sample prediction test.''')
replace_paragraph('04_methods.tex','Each representative partition is evaluated',r'''Cluster quality was evaluated using the Silhouette Score and Davies-Bouldin Index. Both measures were calculated for the same partition in two spaces: the two-dimensional representation and the eight-dimensional scaled financial features. A higher Silhouette Score indicates greater separation, while a lower Davies-Bouldin Index indicates more compact clusters. Euclidean distance was used for evaluation, although the hierarchy used Manhattan distance. This distinction is important because an embedding can produce visibly separated groups without equivalent separation in the underlying financial variables. DBSCAN comparator scores exclude noise observations and are reported with coverage.''')
replace_paragraph('04_methods.tex','Within each date, five seeds',r'''Stability was assessed using the Adjusted Rand Index (ARI) between partitions fitted with different seeds. Five seeds produce ten pairwise comparisons at each date. ARI is unaffected by arbitrary cluster numbering and measures agreement between partitions after allowing for chance. The mean pairwise score summarises consistency under the tested initialisations. Cluster sizes and singleton counts were also examined because a high agreement score can coexist with very small groups. The seed comparisons assess one source of fitting variability; they do not provide independent observations or a confidence interval for changes over time.''')
replace_paragraph('04_methods.tex','Let C be the instruments',r'''Cluster numbers from independent fits cannot be compared directly because their labels are arbitrary. Clusters were therefore matched between adjacent dates using the instruments present at both dates. For an earlier group $A_a$ and a later group $B_b$, Jaccard similarity measures shared continuing members relative to their union. A Hungarian assignment selects the one-to-one matching with the highest total similarity. Positive-overlap matches retain the earlier label, while groups with no overlap receive a new label. Labels that have disappeared are not reused for unrelated groups.''')
replace_paragraph('04_methods.tex','Writing $A_a^C',r'''Let $C$ be the set of instruments observed at both dates. Writing $A_a^C=A_a\cap C$ and $B_b^C=B_b\cap C$, the matching objective is''')
replace_paragraph('04_methods.tex','Temporal ARI is computed',r'''Two forms of temporal comparison were then used. Temporal ARI measures agreement between the partitions of continuing instruments without depending on label matching. The switch count records instruments assigned to different groups after matching. A complete three-date history is described as stable when its aligned label is unchanged and shifted when the label changes at least once. Entries, exits and missing membership are recorded separately. A one-to-one assignment can simplify a split or merger, so the overlap matrices and named member histories are examined alongside the switch counts. Stability in this sense refers to group membership, not unchanged company fundamentals.''')
replace_paragraph('04_methods.tex','For each cluster, we subtract',r'''Cluster interpretation was based first on the original financial characteristics. For each feature, the cluster median was compared with the same-date cross-sectional median in the June 2025 scaled units. Positive deviations indicate relatively high values and negative deviations relatively low values. Equation~\ref{eq:profiles} defines the deviation for cluster $G_{ct}$ within the date-specific population $U_t$. For companies that changed group, their feature changes, previous and new peers, peer retention and destination profiles were also examined. These comparisons show which measured attributes accompany a change in peer relationships.''')
replace_paragraph('04_methods.tex','An XGBoost classifier is fitted',r'''SHAP explanations were generated using an XGBoost surrogate classifier trained to reproduce the cluster labels from the unscaled engineered features. The classifier used 150 trees, a maximum depth of two, a learning rate of 0.05, full row and column sampling, one computational job and a multiclass probability objective. Tree SHAP was applied to its raw class margins using tree-path-dependent perturbation. Additivity was checked with a tolerance of 0.0001. The surrogate was used for interpretation rather than return prediction, and its attributions explain the label-assignment model rather than the clustering algorithm directly.''')
replace_paragraph('04_methods.tex','Where the smallest cluster contains',r'''Surrogate fidelity was assessed using stratified cross-validation where the smallest cluster contained at least two instruments. The number of folds was the smaller of five and the minimum cluster size, with shuffling and the representative seed. Out-of-fold fidelity could not be estimated under this procedure when a cluster contained only one instrument. Reporting fidelity is important because a classifier may reproduce its training labels while providing weaker explanations for held-out instruments. Fidelity measures agreement with cluster labels, not predictive accuracy for financial outcomes.''')
replace_text('04_methods.tex',r'\subsection{Separate financial distance screen}',r'\subsection{Multivariate distance screening}')
replace_paragraph('04_methods.tex','The screen computes squared',r'''A separate Mahalanobis distance analysis was used to identify instruments far from the multivariate sample centre. Squared distances were calculated from the same-date mean and sample covariance in the eight scaled financial features. The calculation uses an internal individual-distance reference, rather than the predictive Hotelling statistic for a new observation. Under independent multivariate normal sampling, the scaled internal distance has the Beta reference in Equation~\ref{eq:distance}. The calculation uses $n=41$ instruments, $p=8$ features and a nominal upper-tail level of 0.05. A singular or excessively ill-conditioned covariance is reported as unestimable.''')
replace_paragraph('04_methods.tex','Those assumptions are doubtful',r'''The distance analysis provides a second view of unusual financial profiles, independently of cluster membership. However, equity cross-sections with heterogeneous, clipped and imputed inputs do not satisfy the normal reference automatically. The resulting flags are therefore descriptive screening signals rather than calibrated significance tests, and no multiple-testing correction establishes them as economic anomalies. Cluster isolation, sector divergence, membership changes and multivariate distance answer different questions and are interpreted separately.''')

replace_text('05_results.tex',r'\section{Empirical results}',r'\section{Results}')
replace_text('05_results.tex',r'\subsection{Cluster quality and the historical comparator}',r'\subsection{Model comparison}')
replace_paragraph('05_results.tex','The largest quality distinction',r'''Table~\ref{tab:5} summarises the performance of the UMAP hierarchical model at each decision date. The Silhouette Score in the reduced representation was 0.685 in June 2025, 0.638 in December 2025 and 0.721 in June 2026. The corresponding scores in the scaled financial features were 0.151, 0.124 and 0.267. These results show clear separation in the UMAP maps but weaker separation in the underlying financial variables. The December partition contained two single-member clusters, while neither June partition contained a singleton. Mean seed ARI was 0.846, 0.892 and 0.738, respectively.''')
replace_paragraph('05_results.tex','The historical t-SNE recipe',r'''Figure~\ref{fig:quality} compares this result with the earlier t-SNE hierarchical specification applied to the current eight-feature dataset. Its embedding Silhouette Scores were 0.532, 0.589 and 0.656, compared with financial-feature scores of 0.195, 0.240 and 0.255. UMAP therefore produced the higher embedding score at all three dates, while t-SNE produced the higher financial-feature score at the first two. The comparison shows why the reduced map and the original financial features should be read together. It does not establish that UMAP is universally superior, and these results are not directly comparable with the earlier paper's different sample and feature set.''')
replace_paragraph('05_results.tex',r'Figure~\ref{fig:seed_variability} shows',r'''Figure~\ref{fig:seed_variability} shows the ten seed-pair comparisons at each date. The December model was the most consistent under the tested seeds, despite containing two singletons. June 2026 showed the greatest seed variation. This indicates that cluster size and seed stability provide different information about the fitted groups.''')
replace_text('05_results.tex',r'\subsection{Continuing members and complete histories}',r'\subsection{Cluster membership over time}')
replace_paragraph('05_results.tex','The second pair is more similar',r'''Table~\ref{tab:6} reports the changes among continuing instruments. Fifteen of the 40 continuing instruments changed aligned group between June and December 2025, compared with 11 between December 2025 and June 2026. Temporal ARI increased from 0.377 to 0.590, indicating greater agreement in the second comparison. Across the 39 instruments observed throughout, 19 retained their aligned group and 20 changed at least once. Five instruments changed in both periods and 15 changed once. These complete histories account for 25 switch events; Mondi contributes the remaining first-period switch before its later exit. The two periods describe different degrees of continuity, but do not establish a statistically significant trend.''')
replace_paragraph('05_results.tex','The 19 stable histories',r'''The stable histories were ANH, BHG, BID, BVT, CFR, FSR, GRT, IMP, INL, INP, MRP, NED, NPH, NRP, OUT, SBK, SHP, SSW and WHL. The shifted histories were ABG, AGL, ANG, BTI, CLS, CPI, DSY, GFI, HAR, MTN, NPN, OMU, PPH, PRX, REM, RNI, SLM, SOL, VAL and VOD. ABG, DSY, OMU, REM and RNI changed in both periods. Figure~\ref{fig:flows} shows these histories, with index entries and exits excluded only from the complete three-date diagram.''')
replace_text('05_results.tex',r'\subsection{Overlap structure and interpretation of switches}',r'\subsection{Interpretation of cluster changes}')
replace_paragraph('05_results.tex','The flow diagram is a compact',r'''Figure~\ref{fig:jaccard} shows the membership overlaps used to match groups across dates. For example, the larger first-period group illustrated in Figure~\ref{fig:alignment} has a matched Jaccard similarity of 0.625. Other matches have lower overlap. The diagram is useful because a retained label can describe a group whose membership has changed substantially. The assignment maximises total overlap across all matched pairs, so each match must also be considered in relation to its actual members.''')
replace_paragraph('05_results.tex','Absa and Old Mutual move',r'''ABSA and Old Mutual provide an example of a temporary change in peer group: both move from aligned group 1 to group 5 and then return to group 1. Reinet follows groups 6, 7 and 2, although its imputed fundamentals require caution. Naspers remains in group 7 at the first two dates and moves to group 9 in June 2026 after the share-basis corrections. These paths do not have the same financial interpretation. They identify cases for further investigation, where the next step is to examine the company's measured feature changes and the composition of its new peer group.''')
replace_text('05_results.tex',r'\subsection{Financial profiles at each decision date}',r'\subsection{Financial feature profiles}')
replace_paragraph('05_results.tex',r'Figures~\ref{fig:profile0}',r'''Figures~\ref{fig:profile0}--\ref{fig:profile2} summarise the financial characteristics of each aligned cluster. The values are cluster-median deviations from the same-date median, measured using the fixed June 2025 scale. Positive values indicate relatively high features and negative values relatively low features. All 41 instruments are included in the date-specific profiles. The aligned labels are used consistently across the figures so changes can be read alongside the membership histories.''')
replace_paragraph('05_results.tex','A precious-metals grouping illustrates',r'''The precious-metals grouping is one of the clearer examples. By December 2025, AngloGold Ashanti, Gold Fields and Harmony are grouped with Impala Platinum, Northam Platinum, Sibanye-Stillwater and Valterra. The group has relatively high one-year return, beta and volatility. Its main membership is retained in June 2026, when Pan African Resources enters the index and joins the group. This provides a financial explanation for the observed similarity, although the analysis does not establish that commodity prices caused the change or that the grouping predicts future returns.''')
replace_paragraph('05_results.tex','ANH, BHG and CFR remain',r'''Anheuser-Busch InBev, BHP and Richemont remain together at all three dates. British American Tobacco joins their group in December 2025, while Prosus leaves by June 2026. The June 2026 group is characterised by high log market capitalisation and low JSE share turnover. This points to similarities in recorded scale and trading activity across firms with different sector labels. However, JSE turnover does not capture all trading in internationally listed firms. The result therefore provides a reason to investigate their financial profiles, rather than to reclassify their businesses.''')
replace_text('05_results.tex',r'\subsection{Representation sensitivity and cluster count}',r'\subsection{Robustness and practical reading}')
replace_paragraph('05_results.tex','The representation sensitivity of',r'''Figure~\ref{fig:feature_sensitivity} compares the complete-history results under the four feature representations. This tests whether the same broad membership interpretation is retained when size, liquidity and share-basis effects are represented differently.''')
replace_paragraph('05_results.tex','Return accounts for',r'''Table~\ref{tab:7} shows that one-year return accounts for 52.5\% of scaled variance in December 2025, compared with 12.5\% under an even eight-variable allocation. The maximum scaled value is 2.847. Thus the June 2025 reference keeps the units constant without keeping each feature's influence constant. The December grouping should be interpreted in light of this concentration, because changes in the geometry can reflect both company attributes and the relative weight of those attributes after scaling.''')
replace_paragraph('05_results.tex','Feature alternatives also affect',r'''The feature alternatives also produce different membership histories. The UMAP model gives 20 stable and 19 shifted histories under original10, 16 and 23 under logsize10, 19 and 20 under invariant8, and 14 and 25 under market5. Each comparison uses the same 39 continuously observed instruments. Figure~\ref{fig:cluster_count} provides the corresponding cluster-count sensitivity from two to twelve groups. These results show that the selected representation and the choice of eight groups influence the financial relationships reported. Internal scores calculated in different feature spaces are not directly comparable as a single ranking of feature sets.''')
replace_text('05_results.tex',r'\subsection{Surrogate fidelity and descriptive distance flags}',r'\subsection{Surrogate interpretation and multivariate outliers}')
replace_paragraph('05_results.tex','Perfect reproduction of training labels',r'''Table~\ref{tab:8} reports the surrogate fidelity. The classifier reproduced all training labels, but out-of-fold agreement was 43.9\% in June 2025 and 70.7\% in June 2026. It could not be estimated for December 2025 under the implemented stratified procedure because two clusters contained only one instrument. These results limit the strength of the SHAP interpretation, particularly at the first two dates. Cluster medians and observed feature histories therefore provide the main explanation, while SHAP describes which variables the fitted surrogate uses to distinguish its assigned labels.''')
replace_paragraph('05_results.tex','Fourteen instrument-date observations',r'''The Mahalanobis distance screen flagged five observations in June 2025, five in December 2025 and four in June 2026, as shown in Table~\ref{tab:9}. These 14 observations cover nine distinct tickers. Sasol was flagged at all three dates, BHP and British American Tobacco at the first two, and Sibanye-Stillwater at the last two. Such repeated flags are useful for follow-up, but their meaning depends on the observation history. Aspen and Pan African Resources were not index members at every date, so missing dates cannot be counted as an absence of unusual behaviour. Anglo American also carries an imputed volume value. The flags remain descriptive because no external event test, forward-return test or calibrated transition null was applied.''')

(sections/'06_discussion.tex').write_text(r'''\section{Discussion}

The results illustrate how repeated unsupervised learning can describe financial relationships within the JSE Top 40 and show where those relationships change. The UMAP hierarchical model produced separated groups in each reduced representation, while the feature profiles and membership comparisons provided a more detailed account of their financial characteristics. The three-date design adds information that was not available in the earlier single-window analysis: whether a company remains with the same peer group, joins a different group or returns to an earlier group.

The model comparison also shows why internal validation must be interpreted carefully. UMAP produced the higher embedding Silhouette Score at every date, but t-SNE produced higher financial-feature scores in June and December 2025. A visually clear map therefore does not establish an equally strong grouping in the original financial variables. The practical value of the representation lies in making relationships easier to examine, while the financial-feature scores indicate how strongly those relationships are supported by the measured inputs.

For equity analysis, the membership histories should be used as a screening layer. ABSA and Old Mutual return to an earlier aligned group, while Reinet and Naspers follow different paths. A change in cluster membership does not prove that a company has become mispriced or experienced an economic structural break. It identifies a relationship that deserves further investigation. An analyst can then examine changes in return, volatility, valuation, scale and trading activity, together with changes in the company's peers.

Interpretability is necessary because a cluster label alone provides limited insight. The median profiles show which financial variables distinguish a group, while company-level histories show how these attributes change over time. The surrogate SHAP analysis provides an additional explanation, but its usefulness depends on fidelity to the cluster labels. Mahalanobis distance gives a separate view of firms far from the multivariate centre. These components answer different questions and make the screening output easier to examine without treating agreement between them as automatic proof of an anomaly.

The South African contribution is a repeated, interpretable financial-clustering case study in a compact equity universe with changing index membership, dual-listed securities and substantial international exposure. Effective-dated membership distinguishes index reconstitution from peer-group movement, while the corrections to share units and Investec line counts show why financial definitions matter in longitudinal comparisons. The method provides a structured way to follow financial similarities over time, with its conclusions conditional on the inputs and modelling choices used.
''',encoding='utf-8')

(sections/'06_limitations_and_future_work.tex').write_text(r'''\section{Limitations and future work}

The study has several limitations. First, the sample is limited to three JSE Top 40 cross-sections and should not be generalised to the full South African equity market without further testing. The same firms recur, adjacent annual market windows overlap by six months and some financial statements are used at more than one date. The 123 instrument-date records therefore do not form 123 independent observations. The two Investec lines also represent one economic company group.

Second, the historical data are retrospectively reconstructed rather than fully certified as information available to an investor on each decision date. Shares and market capitalisation remain reconstructed, the December 2025 Investec allocation is interpolated, Reinet fundamentals are imputed and two Anglo American volume observations are imputed. JSE-only turnover does not capture global trading activity for internationally listed companies. Revenue definitions also differ across sectors. These issues can influence financial similarity even after the documented corrections.

Third, the UMAP settings were selected after examining June 2025, and eight clusters were retained from the earlier study rather than established through independent count selection. With 41 instruments and eight groups, several clusters contain few members, including two December singletons. Random-seed agreement assesses one source of variability but does not rule out sensitivity to the neighbourhood size, minimum distance, linkage, feature definition or preprocessing policy. The feature alternatives and cluster-count sensitivity show that the reported structure depends on these choices.

Fourth, matching groups across dates involves an interpretive choice. The Hungarian assignment maximises total continuing-member Jaccard similarity, but a one-to-one match cannot fully represent cluster splits and mergers. A company's label can change because its own profile changes, its peers change or the refitted embedding changes. Seed ARI does not provide a calibrated probability that an observed switch reflects economic change. The observed periods are also too few to establish a trend in stability.

Fifth, sector labels provide descriptive context but are not independently verified historical ground truth. The surrogate SHAP model explains cluster labels rather than the clustering algorithm itself, and its out-of-fold fidelity is limited or unavailable at some dates. The Mahalanobis reference assumes independent multivariate normal observations, which is not automatically appropriate for these financial cross-sections. Its nominal threshold is therefore a descriptive screen and does not establish statistically significant economic anomalies.

Finally, the study does not conduct portfolio backtesting, test subsequent return co-movement or establish that group changes predict risk or excess returns. Future work should verify point-in-time data availability and freeze inputs and settings before a new decision date. It should assess transition stability under input perturbations, alternative alignment objectives and preprocessing policies, and compare subsequent within-cluster return co-movement with sector-defined and matched random groups. Extending the analysis to more equities and longer periods would also allow the method to be assessed across different market conditions.
''',encoding='utf-8')

(sections/'07_conclusion.tex').write_text(r'''\section{Conclusion}

This article presented an interpretable unsupervised learning workflow for identifying financial peer groups and changes in their membership among JSE Top 40 equities. The analysis covered three decision dates, with 41 listed instruments representing 40 company groups at each date. UMAP dimensionality reduction was combined with average-linkage, Manhattan-distance hierarchical clustering, and the fitted groups were evaluated in both the reduced representation and the scaled financial features.

The model achieved embedding Silhouette Scores of 0.685, 0.638 and 0.721, compared with financial-feature scores of 0.151, 0.124 and 0.267. Among 40 continuing instruments, 15 changed aligned group in the first period and 11 in the second. Of the 39 instruments present throughout, 19 retained their aligned group and 20 changed at least once. The findings describe continuing and changing financial relationships, while showing that visual separation alone is insufficient evidence of strong financial peer structure.

The practical value is to give equity analysts a structured reason to investigate unexpected relationships. Cluster profiles, company feature changes, fidelity-qualified SHAP explanations and multivariate distance screening make the results easier to interpret. The study contributes a repeated South African equity case study and a reproducible framework for following financial peer groups. Its current findings support exploratory screening; external economic validation is needed before claims about structural anomalies or investment performance can be made.
''',encoding='utf-8')

main=paper/'main.tex';s=main.read_text(encoding='utf-8')
needle=r'\input{sections/06_discussion.tex}'
assert s.count(needle)==1
s=s.replace(needle,needle+'\n\n\\FloatBarrier\n\\input{sections/06_limitations_and_future_work.tex}')
main.write_text(s,encoding='utf-8')

pre=paper/'preamble.tex';s=pre.read_text(encoding='utf-8');assert r'\usepackage[round,authoryear]{natbib}' in s
pre.write_text(s.replace(r'\usepackage[round,authoryear]{natbib}',r'\usepackage[numbers,sort&compress]{natbib}'),encoding='utf-8')

# Use citation order for the numerical references, following the designated SACJ paper.
bib=paper/'references.tex';text=bib.read_text(encoding='utf-8')
entries=re.findall(r'(\\bibitem\[[^\n]+?\]\{([^}]+)\}.*?)(?=\\bibitem|\\end\{thebibliography\})',text,re.S)
assert len(entries)==20
lookup={key:entry.strip() for entry,key in entries};order=[]
for name in ['01_introduction.tex','02_related_work.tex','03_population_and_inputs.tex','04_methods.tex','05_results.tex','06_discussion.tex','06_limitations_and_future_work.tex','07_conclusion.tex']:
    for keys in re.findall(r'\\cite[pt]\{([^}]+)\}',(sections/name).read_text(encoding='utf-8')):
        for key in keys.split(','):
            if key not in order:order.append(key)
assert set(order)==set(lookup),(set(lookup)-set(order))
bib.write_text('\\begin{thebibliography}{99}\n\n'+'\n\n'.join(lookup[k] for k in order)+'\n\n\\end{thebibliography}\n',encoding='utf-8')

# Remove editorial descriptions of software from the figure captions in the paper.
caption_updates={
 'flows':'Cluster membership across the three decision dates for the 39 continuously observed instruments. Bold tickers change aligned group at least once. APN, MNP, GLN and PAN are excluded only from this complete-history view. Colours and labels identify aligned groups, not sectors; vertical positions are layout.',
 'cluster_count':'Cluster-count sensitivity from two to twelve groups. Blue lines show financial-feature scores and red lines embedding scores. The numerical results come from the same archived clean run; eight groups remain the reference specification.',
 'evidence':'Interpretation of the screening results. Peer-group changes, financial profiles and multivariate distance provide separate reasons for analyst follow-up. External validation is required before identifying a confirmed economic anomaly.'
}
alltex=list(sections.glob('*.tex'))
for path in alltex:
    s=path.read_text(encoding='utf-8')
    for key,caption in caption_updates.items():
        pattern=r'\\caption\{[^\n]+\}\\label\{fig:'+re.escape(key)+r'\}'
        s=re.sub(pattern,lambda m:r'\caption{'+caption+r'}\label{fig:'+key+'}',s)
    path.write_text(s,encoding='utf-8')

replace_paragraph('appendix_reproducibility.tex','Repository:',r'''The source repository is \url{https://github.com/mygitAN/JSE-Top-40-Clustering}. The reported results come from run 20261115T062631-0c09819ce3c0, generated from clean implementation commit \nolinkurl{98549c660edd410fd74936a03faecadd01f6067b}. Commit \nolinkurl{28c2ccf7a9eab7121b1c8ea9852bbaf22758bd32} subsequently added stricter index-review validation and tests. All files listed in results/manifest.json were checksum-verified during preparation of the manuscript.''')
replace_paragraph('appendix_reproducibility.tex','Population evidence is recorded',r'''Population evidence is recorded in \nolinkurl{data/reference/index_changes.csv}. The June and December 2025 entries link quarterly review notices, September 2025 and March 2026 link reproduced SENS announcements, and June 2026 links a fund factsheet. Not all official notices were directly inspected, and some no-change evidence is secondary. Automated reconciliation against the recorded reviews establishes internal consistency with that evidence, rather than independent historical source certification.''')

readme=paper/'README.md';s=readme.read_text(encoding='utf-8')
if 'sections/06_limitations_and_future_work.tex' not in s:
    s=s.replace('| `sections/06_discussion.tex` | Discussion |','| `sections/06_discussion.tex` | Discussion |\n| `sections/06_limitations_and_future_work.tex` | Limitations and future work |')
if 'designated writing-style reference' not in s:
    s=s.replace('This folder is the working source for future manuscript updates.','This folder is the working source for future manuscript updates. The original\n`SACJ_JSE_Top40.pdf` is the designated writing-style reference.')
readme.write_text(s,encoding='utf-8')

# Confirm that prose editing has preserved every saved result table, diagram input and equation.
before='\n'.join(p.read_text(encoding='utf-8') for p in (backup/'sections').glob('*.tex'))
after='\n'.join(p.read_text(encoding='utf-8') for p in sections.glob('*.tex'))
for env in ['tabularx','equation','align']:
    blocks=lambda s:sorted(re.findall(r'\\begin\{'+env+r'\}.*?\\end\{'+env+r'\}',s,re.S))
    assert blocks(before)==blocks(after),env
assert sorted(re.findall(r'\\diagram\{([^}]+)\}',before))==sorted(re.findall(r'\\diagram\{([^}]+)\}',after))
print('Revised',len(changes),'prose passages; restored the seven-section SACJ sequence; retained 9 tables, 14 diagrams, 7 numbered equations and 20 references.')
